import { ErrorCode, getErrorCodeFromStatus } from "./error-codes.ts";
import { TokenManager, createAuthHeaders } from "./token-manager.ts";
import { createMemoryCache } from "./lru-cache.ts";
import type { LRUCache } from "./lru-cache.ts";
import { mapPath } from "./api-mapping.ts";

export { ErrorCode };

export class SynapseEnhancedError extends Error {
    public readonly code: ErrorCode;
    public readonly detail?: Record<string, unknown>;
    public readonly statusCode: number;
    public readonly retryable: boolean;

    private static readonly RETRYABLE_CODES: Set<ErrorCode> = new Set([
        ErrorCode.TIMEOUT,
        ErrorCode.SERVICE_UNAVAILABLE,
        ErrorCode.RATE_LIMITED,
        ErrorCode.INTERNAL_ERROR,
        ErrorCode.NET_ERROR,
        ErrorCode.UNAVAILABLE,
        ErrorCode.LIMIT_EXCEEDED,
        ErrorCode.THROTTLED,
    ]);

    public constructor(
        message: string,
        code: ErrorCode = ErrorCode.UNKNOWN,
        detail?: Record<string, unknown>,
        statusCode: number = 500,
        retryable?: boolean,
    ) {
        super(message);
        this.name = "SynapseEnhancedError";
        this.code = code;
        this.detail = detail;
        this.statusCode = statusCode;
        this.retryable = retryable ?? SynapseEnhancedError.RETRYABLE_CODES.has(code);
    }

    public static fromResponse(
        message: string,
        statusCode: number,
        detail?: Record<string, unknown>,
    ): SynapseEnhancedError {
        const code = getErrorCodeFromStatus(statusCode);
        const retryable = statusCode >= 500 || statusCode === 429;
        return new SynapseEnhancedError(message, code, detail, statusCode, retryable);
    }

    public static isRetryable(error: Error): boolean {
        if (error instanceof SynapseEnhancedError) {
            return error.retryable;
        }
        return error.name === "AbortError" || error.name === "TimeoutError";
    }
}

export interface JsonBody {
    [key: string]: unknown;
}

export type RequestBody = JsonBody | FormData | Blob | ArrayBuffer | Uint8Array | string;

export interface RequestOptions {
    method?: "GET" | "POST" | "PUT" | "DELETE" | "PATCH";
    body?: RequestBody;
    queryParams?: Record<string, string | number | boolean | undefined | null>;
    headers?: Record<string, string>;
    timeout?: number;
    responseType?: "json" | "text" | "blob";
}

export interface RequestResult<T = unknown> {
    data: T;
    status: number;
}

export interface HttpClientConfig {
    baseUrl: string;
    accessToken: string;
    refreshToken?: string;
    tokenExpiresAt?: number;
    apiPrefix?: string;
    timeout?: number;
    maxRetries?: number;
    retryDelay?: number;
    cacheSize?: number;
    cacheMemoryMB?: number;
    cacheTTL?: number;
}

export class SynapseEnhancedHttpClient {
    private readonly baseUrl: string;
    private tokenManager: TokenManager;
    private readonly apiPrefix: string;
    private readonly timeout: number;
    private readonly maxRetries: number;
    private readonly retryDelay: number;
    private readonly cache: LRUCache<string, unknown>;
    private readonly pendingRequests: Map<string, Promise<RequestResult<unknown>>>;

    private stats = {
        totalRequests: 0,
        cacheHits: 0,
        cacheMisses: 0,
        successfulRequests: 0,
        failedRequests: 0,
        retries: 0,
        totalResponseTime: 0,
    };

    public constructor(options: HttpClientConfig) {
        this.baseUrl = options.baseUrl.replace(/\/$/, "");
        this.tokenManager = new TokenManager({
            accessToken: options.accessToken,
            refreshToken: options.refreshToken,
            expiresAt: options.tokenExpiresAt,
        });
        this.apiPrefix = options.apiPrefix || "/_synapse/client";
        this.timeout = options.timeout ?? 30000;
        this.maxRetries = options.maxRetries ?? 3;
        this.retryDelay = options.retryDelay ?? 1000;
        this.cache = createMemoryCache<string, unknown>({
            max: options.cacheSize ?? 500,
            maxMemoryMB: options.cacheMemoryMB ?? 50,
            defaultTTL: options.cacheTTL ?? 5 * 60 * 1000,
        });
        this.pendingRequests = new Map();
    }

    public updateToken(accessToken: string, refreshToken?: string, expiresAt?: number): void {
        this.tokenManager = new TokenManager({
            accessToken,
            refreshToken: refreshToken ?? this.tokenManager.refreshToken,
            expiresAt: expiresAt ?? this.tokenManager.expiresAt,
        });
    }

    public setTokenRefreshCallback(callback: (refreshToken: string) => Promise<void>): void {
        this.tokenManager = this.tokenManager.clone(callback);
    }

    private buildUrl(
        endpoint: string,
        queryParams?: Record<string, string | number | boolean | undefined | null | unknown>,
    ): string {
        // Apply path mapping based on backend profile
        const mappedEndpoint = mapPath(endpoint);

        let url: string;
        // If endpoint starts with /_matrix or /_synapse, it's a full path
        if (mappedEndpoint.startsWith("/_matrix") || mappedEndpoint.startsWith("/_synapse")) {
            url = `${this.baseUrl}${mappedEndpoint}`;
        } else {
            url = `${this.baseUrl}${this.apiPrefix}${mappedEndpoint}`;
        }

        if (queryParams) {
            const params = new URLSearchParams();
            for (const [key, value] of Object.entries(queryParams)) {
                if (value !== undefined && value !== null) {
                    const stringValue = this.valueToString(value);
                    params.append(key, stringValue);
                }
            }
            const queryString = params.toString();
            if (queryString) {
                url += `?${queryString}`;
            }
        }

        return url;
    }

    private valueToString(value: unknown): string {
        if (value == null) {
            return "";
        }
        if (typeof value === "object") {
            return JSON.stringify(value);
        }
        // eslint-disable-next-line @typescript-eslint/no-base-to-string
        return String(value);
    }

    private getHeaders(extraHeaders?: Record<string, string>): Headers {
        const headers = createAuthHeaders(this.tokenManager);
        headers.set("Content-Type", "application/json");
        headers.set("Accept", "application/json");

        if (extraHeaders) {
            for (const [key, value] of Object.entries(extraHeaders)) {
                headers.set(key, value);
            }
        }

        return headers;
    }

    public async request<T = unknown>(endpoint: string, options: RequestOptions = {}): Promise<RequestResult<T>> {
        const { method = "GET" } = options;

        const cacheKey = this.getCacheKey(endpoint, options);

        // Check cache for GET requests
        if (method === "GET") {
            const cached = this.cache.get(cacheKey) as T | undefined;
            if (cached !== undefined) {
                this.stats.cacheHits++;
                return {
                    data: cached,
                    status: 200,
                };
            }
            this.stats.cacheMisses++;
        }

        // Request deduplication with proper cleanup
        const existingRequest = this.pendingRequests.get(cacheKey);
        if (existingRequest) {
            return existingRequest as Promise<RequestResult<T>>;
        }

        const requestPromise = this.executeRequest<T>(endpoint, options, cacheKey);

        const cleanupPromise = requestPromise.finally(() => {
            this.pendingRequests.delete(cacheKey);
        });

        this.pendingRequests.set(cacheKey, cleanupPromise);

        return requestPromise;
    }

    private async executeRequest<T = unknown>(
        endpoint: string,
        options: RequestOptions,
        cacheKey: string,
    ): Promise<RequestResult<T>> {
        const { method = "GET" } = options;

        let lastError: SynapseEnhancedError | null = null;

        for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
            try {
                const result = await this.fetchRequest<T>(endpoint, options);

                // Cache successful GET requests
                if (method === "GET" && result.status < 300) {
                    this.cache.set(cacheKey, result.data);
                }

                return result;
            } catch (error) {
                lastError =
                    error instanceof SynapseEnhancedError
                        ? error
                        : new SynapseEnhancedError(String(error) || "Unknown error", ErrorCode.UNKNOWN, undefined, 0);

                // Don't retry on client errors (4xx) or last attempt
                if (lastError.statusCode >= 400 && lastError.statusCode < 500) {
                    throw lastError;
                }

                if (attempt < this.maxRetries) {
                    this.stats.retries++;
                    const delay = this.retryDelay * Math.pow(2, attempt);
                    await new Promise((resolve) => setTimeout(resolve, delay));
                }
            }
        }

        throw lastError;
    }

    private async fetchRequest<T = unknown>(endpoint: string, options: RequestOptions): Promise<RequestResult<T>> {
        const { method = "GET", body, queryParams, headers, responseType = "json", timeout } = options;

        const url = this.buildUrl(endpoint, queryParams);
        const requestHeaders = this.getHeaders(headers);

        const controller = new AbortController();
        const timeoutMs = timeout ?? this.timeout;
        const timeoutId = setTimeout(() => controller.abort(), timeoutMs);
        const startTime = Date.now();
        this.stats.totalRequests++;

        try {
            const fetchOptions: RequestInit = {
                method,
                headers: requestHeaders,
                signal: controller.signal,
            };

            if (body && method !== "GET") {
                if (body instanceof FormData) {
                    fetchOptions.body = body;
                    requestHeaders.delete("Content-Type");
                } else {
                    fetchOptions.body = JSON.stringify(body);
                }
            }

            const response = await fetch(url, fetchOptions);

            const duration = Date.now() - startTime;
            this.stats.totalResponseTime += duration;

            const contentType = response.headers.get("content-type") || "";
            let data: T;

            if (responseType === "blob") {
                data = (await response.blob()) as unknown as T;
            } else if (contentType.includes("application/json")) {
                data = await response.json();
            } else {
                data = (await response.text()) as unknown as T;
            }

            if (!response.ok) {
                this.stats.failedRequests++;
                let errorData: { error?: string; message?: string; detail?: Record<string, unknown> } = {};

                if (contentType.includes("application/json") && typeof data === "object" && data !== null) {
                    errorData = data as { error?: string; message?: string; detail?: Record<string, unknown> };
                }

                // Map Matrix error codes to our error codes
                const errorCode = errorData.error || this.getErrorCode(response.status);
                const message = errorData.message || errorData.error || "Unknown error";

                throw new SynapseEnhancedError(message, errorCode as ErrorCode, errorData.detail, response.status);
            }

            this.stats.successfulRequests++;
            return {
                data,
                status: response.status,
            };
        } catch (error) {
            this.stats.failedRequests++;

            if (error instanceof SynapseEnhancedError) {
                throw error;
            }

            if (error instanceof DOMException && error.name === "AbortError") {
                throw new SynapseEnhancedError(
                    `Request timeout after ${timeoutMs}ms`,
                    ErrorCode.TIMEOUT,
                    { timeout: timeoutMs },
                    504,
                );
            }

            if (error instanceof TypeError) {
                throw new SynapseEnhancedError(
                    "Network error",
                    ErrorCode.NET_ERROR,
                    { originalError: String(error) },
                    0,
                );
            }

            throw new SynapseEnhancedError(String(error) || "Unknown error", ErrorCode.UNKNOWN, undefined, 0);
        } finally {
            // Always clear the timeout to prevent memory leaks
            clearTimeout(timeoutId);
        }
    }

    private getErrorCode(status: number): ErrorCode {
        const errorCodeMap: Record<number, ErrorCode> = {
            400: ErrorCode.INVALID_PARAM,
            401: ErrorCode.UNKNOWN_TOKEN,
            403: ErrorCode.FORBIDDEN,
            404: ErrorCode.NOT_FOUND,
            429: ErrorCode.LIMIT_EXCEEDED,
            500: ErrorCode.INTERNAL_ERROR,
            503: ErrorCode.UNAVAILABLE,
        };
        return errorCodeMap[status] || ErrorCode.UNKNOWN;
    }

    public get<T = unknown>(
        endpoint: string,
        queryParams?: Record<string, string | number | boolean | undefined | null | unknown>,
    ): Promise<RequestResult<T>> {
        return this.request<T>(endpoint, {
            method: "GET",
            queryParams: queryParams as Record<string, string | number | boolean | undefined | null>,
        });
    }

    public post<T = unknown>(
        endpoint: string,
        body?: Record<string, unknown> | FormData,
        queryParams?: Record<string, string | number | boolean | undefined | null>,
    ): Promise<RequestResult<T>> {
        return this.request<T>(endpoint, { method: "POST", body, queryParams });
    }

    public put<T = unknown>(
        endpoint: string,
        body?: Record<string, unknown>,
        queryParams?: Record<string, string | number | boolean | undefined | null>,
    ): Promise<RequestResult<T>> {
        return this.request<T>(endpoint, { method: "PUT", body, queryParams });
    }

    public delete<T = unknown>(
        endpoint: string,
        queryParams?: Record<string, string | number | boolean | undefined | null>,
    ): Promise<RequestResult<T>> {
        return this.request<T>(endpoint, { method: "DELETE", queryParams });
    }

    public upload<T = unknown>(endpoint: string, body: FormData): Promise<RequestResult<T>> {
        return this.request<T>(endpoint, {
            method: "POST",
            body,
            headers: {},
            responseType: "json",
        });
    }

    public getStats(): {
        requests: number;
        errors: number;
        totalRequests: number;
        cacheHits: number;
        cacheMisses: number;
        cacheHitRate: number;
        successfulRequests: number;
        failedRequests: number;
        retries: number;
        averageResponseTime: number;
    } {
        const cacheStats = this.cache.getStats();
        return {
            requests: this.stats.totalRequests,
            errors: this.stats.failedRequests,
            totalRequests: this.stats.totalRequests,
            cacheHits: cacheStats.hitCount,
            cacheMisses: cacheStats.missCount,
            cacheHitRate: cacheStats.hitRate,
            successfulRequests: this.stats.successfulRequests,
            failedRequests: this.stats.failedRequests,
            retries: this.stats.retries,
            averageResponseTime:
                this.stats.successfulRequests > 0 ? this.stats.totalResponseTime / this.stats.successfulRequests : 0,
        };
    }

    public clearCache(): void {
        this.cache.clear();
        this.stats.cacheHits = 0;
        this.stats.cacheMisses = 0;
    }

    public setDefaultCacheTTL(ttl: number): void {
        if (ttl <= 0) {
            throw new SynapseEnhancedError("Cache TTL must be a positive number", ErrorCode.INVALID_PARAM);
        }
    }

    public invalidateCache(endpoint: string, method: string = "GET"): number {
        return this.cache.invalidateByPrefix(`${method}:${endpoint}`);
    }

    public getCacheSize(): number {
        return this.cache.size;
    }

    /**
     * Generate a simple hash from a string for cache keys
     * Uses a simple DJB2-style hash algorithm to avoid cache key collisions
     * @param str - The string to hash
     * @returns A hexadecimal hash string
     */
    private simpleHash(str: string): string {
        let hash = 5381;
        for (let i = 0; i < str.length; i++) {
            const char = str.charCodeAt(i);
            hash = (hash * 33) ^ char;
        }
        // Convert to hex string
        return (hash >>> 0).toString(16);
    }

    /**
     * Generate a cache key from endpoint and options
     * Uses a hash function for the query parameters to prevent cache poisoning
     * @param endpoint - The API endpoint
     * @param options - Request options including method and query parameters
     * @returns A cache key string
     */
    private getCacheKey(endpoint: string, options: RequestOptions): string {
        const { method = "GET", queryParams } = options;
        // Hash the query parameters to prevent injection and keep key length reasonable
        const paramsHash = queryParams ? this.simpleHash(JSON.stringify(queryParams)) : "";
        return `${method}:${endpoint}:${paramsHash}`;
    }

    public destroy(): void {
        this.clearCache();
        this.pendingRequests.clear();
    }
}
